package pac;
public final class BallExchangeTest {
 private static void check(boolean b,String m){if(!b)throw new RuntimeException(m);}
 public static void checkIcons(){PixelFont font=new PixelFont("tahoma_7b",true);for(int i=0;i<3;i++){String icon=BallArt.symbol(i);check(icon.length()==1&&BallArt.symbolType(icon.charAt(0))==i,"inline icon type");check(font.width(icon)==14&&font.width("10 "+icon)==font.width("10 ")+14,"inline icon measure");check(BallArt.name(i).equals(icon),"text ball label returned");}check(BallArt.symbolType('A')==-1,"ordinary letter interpreted as icon");System.out.println("BallIcons OK: normal/silver/gold markers, inline width and currency labels");}
 public static void run(){int n=Save.balls,s=Save.silverBalls,g=Save.goldBalls;Save.balls=9;Save.silverBalls=Save.goldBalls=0;check(!BallExchange.exchange(0)&&Save.balls==9,"insufficient silver");Save.balls=110;check(BallExchange.exchange(0)&&Save.balls==100&&Save.silverBalls==1,"silver rate");check(BallExchange.exchange(1)&&Save.balls==0&&Save.goldBalls==1,"gold rate");check(!BallExchange.exchange(1)&&!BallExchange.exchange(-1)&&!BallExchange.exchange(2)&&Save.balls==0,"invalid exchange");Save.balls=100;Save.silverBalls=2147483647;check(!BallExchange.exchange(0)&&Save.balls==100,"overflow spent balance");Save.goldBalls=2147483647;check(!BallExchange.exchange(1)&&Save.balls==100,"gold overflow");Save.balls=n;Save.silverBalls=s;Save.goldBalls=g;System.out.println("BallExchangeTest OK: rates, insufficient funds, invalid routes and overflow");}
}
